'use strict';
/**
 * Browser bundle for the v1 engine, built at runtime by the server. No bundler, no build step.
 *
 * WHAT THIS IS FOR
 * The site used to run `src/core/ai-core.js` in the browser via `/js/ai-core.js`. That engine is a
 * separate implementation with a different evaluation, and it loops. The site now runs the real
 * `quoridor-engine/engines/v1`, the same one the server-side bots and the arena use.
 *
 * The engine is CommonJS and depends on two modules:
 *   require('../../rules')       -> the canonical rules, which the browser already has as the global
 *                                   `Shared` from /shared.js. Rules are NEVER duplicated here.
 *   require('../../tools/rng')   -> pure JS with no Node API, so its source is embedded verbatim.
 *
 * The whole thing is wrapped in a three-line module registry. That is not a bundler: there is no
 * dependency graph walk, no transpilation and no duplicated code, just the two source files and a
 * `require` that resolves to `Shared` for the rules.
 *
 * STRICT MODE
 * The wrapper IIFE is strict, so the embedded `'use strict'` at the top of each source file being
 * preceded by the injected `require` shim does not cost us anything: everything nested inside a
 * strict function is strict regardless of directive position.
 *
 * CACHING
 * The result is cached in memory. Changing the engine therefore requires a server restart, which is
 * also what deploys do. Browsers additionally need the `?v=` bump in frontend/index.html.
 */

const fs = require('fs');
const path = require('path');

const ENGINE_DIR = path.join(__dirname, '..', '..', 'quoridor-engine');
const RNG_FILE = path.join(ENGINE_DIR, 'tools', 'rng.js');
const V1_FILE = path.join(ENGINE_DIR, 'engines', 'v1', 'index.js');
const MOVES_FILE = path.join(ENGINE_DIR, 'rules', 'moves.js');

/**
 * The four bot tiers. Depth only, no randomness.
 *
 * These are the depths measured in the arena as monotonically stronger (easy d2 -> expert d5, no
 * inversions). `DEPTH_BY_DIFFICULTY` inside engines/v1 is deliberately NOT used: it still carries the
 * old values, including impossible = 20, and depth 9 measures worse than depth 5.
 */
const DIFFICULTY_DEPTH = { easy: 2, medium: 3, hard: 4, impossible: 5 };

const DEFAULT_MAX_DEPTH = 3;

/**
 * Depth for a difficulty label. Callers pass maxDepth explicitly to the engine, so this is the only
 * place where a label turns into a number.
 */
function difficultyToMaxDepth(difficulty) {
    const d = DIFFICULTY_DEPTH[difficulty];
    return d === undefined ? DEFAULT_MAX_DEPTH : d;
}

let cached = null;

function buildAiV1Bundle() {
    if (cached) return cached;

    // Normalised to LF: the wrapper below is joined with \n, and the working tree is CRLF on Windows.
    const rngSrc = fs.readFileSync(RNG_FILE, 'utf8').replace(/\r\n/g, '\n');
    const v1Src = fs.readFileSync(V1_FILE, 'utf8').replace(/\r\n/g, '\n');
    const movesSrc = fs.readFileSync(MOVES_FILE, 'utf8').replace(/\r\n/g, '\n');

    cached = [
        '/* Quoridor AI v1 - generated by src/core/ai-v1-bundle.js. Do not edit by hand. */',
        '(function (global) {',
        '  "use strict";',
        '  var __defs = {};',
        '  var __cache = {};',
        '  function __req(id) {',
        '    if (__cache[id]) return __cache[id].exports;',
        '    var m = { exports: {} };',
        '    __cache[id] = m;',
        '    __defs[id](m, m.exports);',
        '    return m.exports;',
        '  }',
        '  __defs["tools/rng"] = function (module, exports) {',
        rngSrc,
        '  };',
        '  __defs["rules/moves"] = function (module, exports) {',
        movesSrc,
        '  };',
        '  __defs["engines/v1"] = function (module, exports) {',
        '    var require = function (id) {',
        '      if (id === "../../rules") {',
        '        if (!global.Shared) {',
        '          throw new Error("AI v1: /shared.js must be loaded before /js/ai-v1.js");',
        '        }',
        '        return global.Shared;',
        '      }',
        '      if (id === "../../rules/moves") return __req("rules/moves");',
        '      if (id === "../../tools/rng") return __req("tools/rng");',
        '      throw new Error("AI v1: unexpected require(" + id + ")");',
        '    };',
        v1Src,
        '  };',
        '  var v1 = __req("engines/v1");',
        '  global.AiV1 = {',
        '    createEngineV1: v1.createEngineV1,',
        '    DEFAULT_WEIGHTS: v1.DEFAULT_WEIGHTS,',
        // Emitted from the constant above rather than from a second hand-written copy, so the server
        // and the browser cannot disagree about which label means which depth.
        '    DIFFICULTY_DEPTH: ' + JSON.stringify(DIFFICULTY_DEPTH) + ',',
        '    DEFAULT_MAX_DEPTH: ' + DEFAULT_MAX_DEPTH + ',',
        '    difficultyToMaxDepth: function (difficulty) {',
        '      var d = ' + JSON.stringify(DIFFICULTY_DEPTH) + '[difficulty];',
        '      return d === undefined ? ' + DEFAULT_MAX_DEPTH + ' : d;',
        '    },',
        '  };',
        '}(typeof self !== "undefined" ? self : this));',
    ].join('\n');

    return cached;
}

module.exports = {
    buildAiV1Bundle,
    difficultyToMaxDepth,
    DIFFICULTY_DEPTH,
    DEFAULT_MAX_DEPTH,
};
